  HDL_Counter_process : PROCESS (clk, aresetn)
  BEGIN
    IF aresetn = '0' THEN
      HDL_Counter_out1 <= to_unsigned(16#0#, 3);
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        IF HDL_Counter_out1 >= to_unsigned(16#4#, 3) THEN 
